SELECT sc.SEC_SNAME AS `股票名称`, sc.SEC_CODE AS `股票代码`, inc.ENDDATE AS `报表截止日`, ROUND(inc.P110101/100000000, 3) AS `营业收入(亿)` FROM VIEW_STK_INCOME_GEN inc JOIN GET_A_SEC_CODE sc ON inc.COMCODE = sc.COMCODE AND sc.ISVALID=1 WHERE sc.SEC_SNAME LIKE '%宁德时代%' AND inc.RPT_TYPE = '合并' AND inc.P110101 IS NOT NULL AND YEAR(inc.ENDDATE) = 2025 AND MONTH(inc.ENDDATE) = 12 AND DAY(inc.ENDDATE) = 31 ORDER BY inc.ENDDATE DESC LIMIT 1;
